FileBackedBlobFactoryAsyncWaiter::~FileBackedBlobFactoryAsyncWaiter() = default;


void FileBackedBlobFactoryAsyncWaiter::RegisterBlob(
    ::mojo::PendingReceiver<::blink::mojom::blink::Blob> blob, const ::blink::String& content_type, ::blink::mojom::blink::DataElementFilePtr file, bool block_on_registration, ::blink::String* out_uuid) {
  base::RunLoop loop;
  proxy_->RegisterBlob(
      std::move(blob),
      std::move(content_type),
      std::move(file),
      std::move(block_on_registration),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::blink::String* out_uuid
,
             const ::blink::String& uuid) {*out_uuid = std::move(uuid);
            loop->Quit();
          },
          &loop,
          out_uuid));
  loop.Run();
}

::blink::String FileBackedBlobFactoryAsyncWaiter::RegisterBlob(
    ::mojo::PendingReceiver<::blink::mojom::blink::Blob> blob, const ::blink::String& content_type, ::blink::mojom::blink::DataElementFilePtr file, bool block_on_registration) {
  ::blink::String async_wait_result;
  RegisterBlob(std::move(blob),std::move(content_type),std::move(file),std::move(block_on_registration),&async_wait_result);
  return async_wait_result;
}






